// === Tab: mySketch ===
let jmSh;

function setup() {
      createCanvas(1112,834,WEBGL);
      rectMode(CENTER);
      noStroke();
      fill(0);
      jmSh=createShader(vert,frag);   
}


function draw() {
    this.shader(jmSh);
    background(255,0.0,0.0);
    jmSh.setUniform("resolution", [width, height]); 
    jmSh.setUniform("time", millis() / 1000.0); 
    rect(0,0,width,height);

}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  }
}

var vert= `
     #ifdef GL_ES
      precision highp float;
      #endif

    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;
    attribute vec4 aVertexColor;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec4 var_vertCol;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;

    void main() {
      gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);

      // just passing things through
      var_vertPos      = aPosition;
      var_vertCol      = aVertexColor;
      var_vertNormal   = aNormal;
      var_vertTexCoord = aTexCoord;
    }

`;

var frag=`

#ifdef GL_ES
precision highp float;
#endif



uniform vec2 resolution;
uniform float time;

const float nb=0.02;

vec4 quaternion(vec3 axis, float phi){
  return vec4(axis*sin(phi/2.0),cos(phi/2.0));}

vec3 qtourne(vec4 q, vec3 v){return v+2.0*cross(cross(v,q.xyz)-q.w*v,q.xyz);}

vec3 coupe(vec2 st)
{ 
  vec4 quat=quaternion(normalize(vec3(sin(0.06*time),sin(0.06*time),cos(0.06*time))),time*0.4);
  vec3  st3=vec3(-5.0*(st.x),-0.001*st.y*st.x,-3.3010*(st.y-st.x));
  vec3 col=normalize(vec3(st3.x+1.2,st3.y+1.2,st3.z*sin(0.5*time)));
  st3=qtourne(quat,col+st3);
  st=st3.xy*nb;
  float prd=pow(pow(abs(st.x),abs(st.y)*30.0),pow(abs(st.y),abs(st.x*3.0)));
  if((mod(prd,2.0) <0.01) ) {col=0.01*st3;}
  return col;
}
void main(void)
{
    vec2 ps = gl_FragCoord.xy / resolution.xy;
    ps=ps*200.0 - vec2(200.0);
    vec3 colo1=coupe(-ps*0.1*vec2(17.0,-30.0));
    vec3 colo2=coupe(ps+vec2(23.0,10.0));
    vec3 colo3=coupe(ps/vec2(-43.0,11.0));
      gl_FragColor=vec4(colo1*colo3+colo1+colo2,1.0);
}   
`;

